import {suggestPlans} from './blend-plan.mjs';
import {defaults,evaluate,PRODUCT_TARGETS,EQUIPMENT,ALLOYS} from './blend-model.mjs';
const elLabels={C:'C / %',Si:'Si / %',Mn:'Mn / %',Al:'Al / %',Cr:'Cr / %',Ni:'Ni / %',Mo:'Mo / %',P:'P / %',S:'S / %',Cu:'Cu / %',Sn:'Sn / %',Odiss:'溶解氧 / ppm',TO:'总氧 / ppm',H:'H / ppm',N:'N / ppm'};
const n=v=>Number.isFinite(+v)?Number(v).toLocaleString('zh-CN',{maximumFractionDigits:4}):'—';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountBlendModel(options={}){
 const host=options instanceof HTMLElement?options:(options.host || document.getElementById(options.hostId||'blend-root'));
 if(!host)return;let candidates=[];let config;try{config=JSON.parse(localStorage.getItem('steel-blend-v1'))}catch{}config ||= defaults('structural');config.equipment ||= structuredClone(EQUIPMENT);for(const stage of config.route)stage.additions ||= [];
 const input=(path,value,label)=>`<label>${esc(label)}<input type="number" step="any" data-path="${path}" value="${esc(value)}" aria-label="${esc(label)}"></label>`;
 function render(){host.innerHTML=`<div class="blend-shell"><header class="blend-head"><div><p class="overline">MIX · REFINE · VERIFY</p><h2>混合钢水统一精炼</h2><p>先做质量与热量守恒，再计算工序处理能力、消耗和终点差距。</p></div><span class="blend-tag">未标定的机理估算</span></header><div class="blend-note">三类产品独立建组；目标为可编辑的研究设定。速率常数与收得率需用实际炉次校准；文献条件不能直接外推为设备保证值。</div><section class="blend-card"><div class="blend-toolbar"><h3>1 · 来料与混合</h3><button class="button light small" data-add-feed>＋ 添加一股钢水</button></div><p class="blend-help">成分均为质量百分数；气体与氧指标使用 ppm。横向滚动可填写残余元素。</p><div class="blend-scroll"><table><thead><tr><th>来料</th><th>重量 / t</th><th>温度 / °C</th><th>比热 / kJ·kg⁻¹·K⁻¹</th>${Object.values(elLabels).map(x=>`<th>${x}</th>`).join('')}<th></th></tr></thead><tbody>${config.feeds.map((f,i)=>`<tr><td><input data-path="feeds.${i}.name" value="${esc(f.name)}" aria-label="来料${i+1}名称"></td>${['mass_t','T','cp',...Object.keys(elLabels)].map(k=>`<td><input type="number" step="any" data-path="feeds.${i}.${k}" value="${esc(f[k])}" aria-label="来料${i+1} ${k}"></td>`).join('')}<td><button class="text-button" data-del-feed="${i}" ${config.feeds.length<2?'disabled':''}>移除</button></td></tr>`).join('')}</tbody></table></div><div class="blend-fields">${input('mixLossKWh',config.mixLossKWh,'混合散热 / kWh')}${input('liquidus',config.liquidus,'液相线参考 / °C')}</div></section><section class="blend-card"><h3>2 · 产品目标与工序</h3><label>产品组 <select data-family><option value="structural">低合金结构钢</option><option value="bearing">轴承钢</option><option value="stainless">不锈钢</option></select></label><p class="blend-help">切换产品组会载入该组示例来料、目标和工序。删除或调整工序后重新计算。</p><details><summary>编辑终点目标</summary><div class="blend-fields">${Object.entries(config.targets||{}).map(([k,v])=>typeof v==='number'?input('targets.'+k,v,k+' 上限'):Array.isArray(v)?v.map((x,j)=>input('targets.'+k+'.'+j,x,(elLabels[k]||k)+(j?' 上限':' 下限'))).join(''):Object.entries(v||{}).map(([a,x])=>input('targets.'+k+'.'+a,x,k+' '+a)).join('')).join('')}</div></details><div class="blend-scroll"><table><thead><tr><th>设备</th><th>时间 / min</th><th>氩气 / NL·min⁻¹</th><th>粉 / kg·min⁻¹</th><th>铝 / kg</th><th>氧 / Nm³</th><th>输入功率 / kW</th><th></th></tr></thead><tbody>${config.route.map((s,i)=>`<tr><td>${esc(s.type)}</td>${['time','gasNLmin','powderKgMin','AlKg','oxygenNm3','heatKW'].map(k=>`<td><input type="number" step="any" data-path="route.${i}.${k}" value="${esc(s[k]??0)}" aria-label="第${i+1}段 ${k}"></td>`).join('')}<td><button class="text-button" data-up-stage="${i}" ${i===0?'disabled':''}>上移</button> <button class="text-button" data-del-stage="${i}">移除</button></td></tr>`).join('')}</tbody></table></div><div class="blend-toolbar"><select data-equipment aria-label="添加设备">${(Array.isArray(EQUIPMENT)?EQUIPMENT.map(x=>typeof x==='string'?x:x.type):Object.keys(EQUIPMENT)).map(k=>`<option>${esc(k)}</option>`).join('')}</select><button class="button light small" data-add-stage>添加设备</button></div><details><summary>合金加入（按工序、载体与收得率核算）</summary><p class="blend-help">每段可添加多种合金；质量是投入量，收得率为 0–1。合金组成采用模型的示例载体，不代表采购品化验。</p>${config.route.map((stage,i)=>`<h4>第 ${i+1} 段 · ${esc(stage.type)}</h4>${(stage.additions||[]).map((a,j)=>`<div class="blend-alloy"><label>载体<select data-alloy-type="${i}.${j}">${Object.keys(ALLOYS).map(k=>`<option value="${k}" ${k===a.type?'selected':''}>${k}</option>`).join('')}</select></label>${input('route.'+i+'.additions.'+j+'.kg',a.kg,'投入 / kg')}${input('route.'+i+'.additions.'+j+'.recovery',a.recovery,'收得率 / 0–1')}<button class="text-button" data-del-alloy="${i}.${j}">移除</button></div>`).join('')}<button class="button light small" data-add-alloy="${i}">＋ 加入合金</button>`).join('')}</details><details><summary>编辑设备能力上限</summary><p class="blend-help">示例设备上限须用现场设备参数替换，未考虑并行炉次排队。</p>${Object.entries(config.equipment||EQUIPMENT).map(([type,eq])=>`<h4>${esc(type)}</h4><div class="blend-fields">${Object.entries(eq).map(([k,v])=>input('equipment.'+type+'.'+k,v,({maxBatchT:'炉容 / t',maxGasNLmin:'氩气上限 / NL·min⁻¹',maxPowderKgMin:'喷粉上限 / kg·min⁻¹',maxHeatKW:'加热上限 / kW'})[k]||k)).join('')}</div>`).join('')}</details><details><summary>模型参数与设备能力假设</summary><div class="blend-fields">${Object.entries(config.params).map(([k,v])=>input('params.'+k,v,({Ls:'硫分配比 Ls',slagKgPerT:'新渣 / kg·t⁻¹',slagSwt:'新渣 S / %',kS:'脱硫 kS / min⁻¹',kO:'脱氧 kO / min⁻¹',kH:'脱氢 kH / min⁻¹',kC:'脱碳 kC / min⁻¹',pressurePa:'真空压力 / Pa',heatEfficiency:'加热效率 / 0–1',coolingKMin:'温降 / K·min⁻¹',crOxygenFraction:'铬分氧份额 / 0–1'})[k]||k)).join('')}</div><p class="blend-help">这些参数是可调整的建模假设，未声称来自同一篇论文或同一炉次。</p></details></section><div class="blend-toolbar"><button class="button" data-run>计算混合与精炼结果</button><button class="button light" data-plans>比较可行工艺情景</button><button class="button light" data-reset>恢复当前组示例</button><span class="blend-help" data-status></span></div><div data-candidates></div><div data-results aria-live="polite"></div><section class="blend-card"><h3>公式与证据边界</h3><p>混合成分：wⱼ = Σ(mᵢwᵢⱼ) / Σmᵢ。混合温度依据 Σ(mᵢcₚᵢTᵢ) − Q损失 的显热平衡。</p><p>动力学参考：dc/dt = −k(c − c*)；c(t) = c* + (c₀ − c*)exp(−kt)。硫同时满足钢渣质量守恒与 Ls = (S)渣/[S]钢；真空脱气的平衡需考虑分压与活度。</p><p>气量 = NL/min × min / 1000；粉耗 = kg/min × min。加热输入电耗 = kW × min / 60，钢液得热还需乘热效率。</p><p><a href="https://doi.org/10.1002/srin.202300330" target="_blank" rel="noopener">Si–Mn 钢精炼耦合模型（2024）</a>：支持钢液、渣与夹杂物耦合建模。<a href="https://doi.org/10.3390/met13071229" target="_blank" rel="noopener">VD 脱氢模拟（2023）</a>：105 t、66 Pa、260 NL/min、18 min 为特定案例。<a href="https://doi.org/10.1007/s42243-023-00973-x" target="_blank" rel="noopener">RH 喷粉模型（2023）</a>：粉体输运条件不能直接视为通用脱硫效率。</p></section></div>`;host.querySelector('[data-family]').value=config.family;calculate();}
 function calculate(){let r;try{r=evaluate(config)}catch(e){host.querySelector('[data-results]').innerHTML=`<div class="blend-note">计算未完成：${esc(e.message)}</div>`;return}localStorage.setItem('steel-blend-v1',JSON.stringify(config));const area=host.querySelector('[data-results]');if(!r.valid){area.innerHTML=`<div class="blend-note">${(r.errors||[]).map(esc).join('<br>')}</div>`;return}const m=r.mixed||{},t=r.totals||{};area.innerHTML=`<section class="blend-card"><h3>3 · 混合状态</h3><div class="blend-kpis">${[['总量',m.mass_t,'t'],['温度',m.T,'°C'],['C',m.C,'%'],['S',m.S,'%'],['溶解氧',m.Odiss,'ppm'],['总氧',m.TO,'ppm']].map(([l,v,u])=>`<div><span>${l}</span><strong>${n(v)} <small>${u}</small></strong></div>`).join('')}</div></section><section class="blend-card"><h3>4 · 分段处理能力与效率</h3><div class="blend-scroll"><table><thead><tr><th>工序</th><th>时间 / min</th><th>S 入→出 / %</th><th>C 入→出 / %</th><th>溶解氧 入→出 / ppm</th><th>H 入→出 / ppm</th><th>温度 入→出 / °C</th><th>脱硫率</th></tr></thead><tbody>${r.stages.map(s=>`<tr><td>${esc(s.type)}</td><td>${n(s.time)}</td>${['S','C','Odiss','H','T'].map(k=>`<td>${n(s.in?.[k])} → ${n(s.out?.[k])}</td>`).join('')}<td>${s.in?.S>0?n((s.in.S-s.out.S)/s.in.S*100)+'%':'—'}</td></tr>`).join('')}</tbody></table></div></section><section class="blend-card"><h3>5 · 时间、气体与物料总账</h3><div class="blend-kpis">${Object.entries(t).map(([k,v])=>`<div><span>${({time:'总时间 / min',gasNm3:'氩气 / Nm³',powderKg:'粉料 / kg',oxygenNm3:'氧气 / Nm³',energyKWh:'输入电耗 / kWh',AlKg:'铝料 / kg'})[k]||esc(k)}</span><strong>${n(v)}</strong><small>${k==='time'?'':n(v/m.mass_t)+' / t钢'}</small></div>`).join('')}</div></section><section class="blend-card"><h3>合金物料分账</h3><div class="blend-scroll"><table><thead><tr><th>工序</th><th>载体</th><th>投入 / kg</th><th>收得率</th><th>进入钢液 / kg</th><th>未收得 / kg</th></tr></thead><tbody>${r.stages.flatMap((s,i)=>(s.alloyLedger||[]).map(a=>`<tr><td>${i+1} · ${esc(s.type)}</td><td>${esc(a.type)}</td><td>${n(a.kg)}</td><td>${n(a.recovery)}</td><td>${n(a.retainedKg)}</td><td>${n(a.rejectedKg)}</td></tr>`)).join('')||'<tr><td colspan="6">当前没有通用合金加入；铝料已列于总账。</td></tr>'}</tbody></table></div><h3>6 · 终点与约束检查</h3><p class="blend-tag">${r.feasible?'所计算约束满足；仍需独立验证产品质量':'存在未满足指标或能力约束'}</p><div class="blend-scroll"><table><thead><tr><th>指标（% 或 ppm）</th><th>预测</th><th>下限</th><th>上限</th><th>判断</th></tr></thead><tbody>${(r.checks||[]).map(c=>`<tr><td>${esc(elLabels[c.element]||c.element)}</td><td>${n(c.value)}</td><td>${c.min==null?'—':n(c.min)}</td><td>${c.max==null?'—':n(c.max)}</td><td class="${c.pass?'blend-pass':'blend-fail'}">${c.pass?'满足':'未满足'}</td></tr>`).join('')}</tbody></table></div><div class="blend-note">${(r.warnings||[]).map(x=>esc(typeof x==='string'?x:JSON.stringify(x))).join('<br>')||'未报告额外警示。'}<br>不支持的反应、夹杂物尺寸与形态、实际收得率及排产限制需单独核定；结果不是产品认证。</div><details><summary>设备能力默认上限（假设，非厂家保证）</summary><div class="blend-scroll"><table><thead><tr><th>设备</th><th>炉容 / t</th><th>氩气 / NL·min⁻¹</th><th>喷粉 / kg·min⁻¹</th><th>加热 / kW</th></tr></thead><tbody>${Object.entries(config.equipment||EQUIPMENT).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${n(v.maxBatchT)}</td><td>${n(v.maxGasNLmin)}</td><td>${n(v.maxPowderKgMin)}</td><td>${n(v.maxHeatKW)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>模型假设与未求解项</summary>${Object.entries(r.assumptions||{}).map(([k,v])=>`<p>${esc(v)}</p>`).join('')}<p>尚未建立统计置信区间；未计算高低参数情景，不输出虚构误差范围。</p></details></section>`;host.querySelector('[data-status]').textContent='已按当前输入重新计算';}
 host.addEventListener('input',e=>{e.stopPropagation();const p=e.target.dataset.path;if(!p)return;let obj=config;const parts=p.split('.');for(const k of parts.slice(0,-1))obj=obj[k];obj[parts.at(-1)]=e.target.type==='number'?e.target.valueAsNumber:e.target.value;host.querySelector('[data-candidates]').innerHTML='';candidates=[];host.querySelector('[data-status]').textContent='输入已修改，请重新计算';host.querySelector('[data-results]').innerHTML='<div class="blend-note">输入已改变，先前结果已作废。请重新计算。</div>';});
 host.addEventListener('change',e=>{e.stopPropagation();if(e.target.dataset.alloyType){const [i,j]=e.target.dataset.alloyType.split('.').map(Number);config.route[i].additions[j].type=e.target.value;calculate()}if(e.target.matches('[data-family]')){config=defaults(e.target.value);render()}});
 host.addEventListener('click',e=>{e.stopPropagation();const b=e.target.closest('button');if(!b)return;if(b.dataset.addAlloy!==undefined){const stage=config.route[+b.dataset.addAlloy];stage.additions ||= [];stage.additions.push({type:Object.keys(ALLOYS)[0],kg:0,recovery:.95});render()}if(b.dataset.delAlloy!==undefined){const [i,j]=b.dataset.delAlloy.split('.').map(Number);config.route[i].additions.splice(j,1);render()}if(b.hasAttribute('data-plans')){try{candidates=suggestPlans(config);host.querySelector('[data-candidates]').innerHTML='<section class="blend-card"><h3>有限工艺情景比较</h3><p class="blend-help">固定规则生成的候选，不是全局最优解。未满足约束的候选仍列出以显示差距。</p>'+candidates.map((c,i)=>`<div class="blend-plan"><strong>${esc(c.label)}</strong><span>${c.result?.valid?'时间 '+n(c.result.totals?.time)+' min · 氩 '+n(c.result.totals?.gasNm3)+' Nm³ · '+(c.result.feasible?'计算约束满足':'存在差距'):'输入无效'}</span><button class="button light small" data-use-plan="${i}">采用此情景</button></div>`).join('')+'</section>'}catch(error){host.querySelector('[data-candidates]').innerHTML='<div class="blend-note">'+esc(error.message)+'</div>'}}if(b.dataset.usePlan!==undefined){config=structuredClone(candidates[+b.dataset.usePlan].config);render()}if(b.hasAttribute('data-run'))calculate();if(b.hasAttribute('data-reset')){config=defaults(config.family);render()}if(b.hasAttribute('data-add-feed')){config.feeds.push({...config.feeds[0],name:'新来料 '+(config.feeds.length+1)});render()}if(b.dataset.delFeed!==undefined){config.feeds.splice(+b.dataset.delFeed,1);render()}if(b.dataset.upStage!==undefined){const i=+b.dataset.upStage;if(i>0){[config.route[i-1],config.route[i]]=[config.route[i],config.route[i-1]];render()}}if(b.dataset.delStage!==undefined){config.route.splice(+b.dataset.delStage,1);render()}if(b.hasAttribute('data-add-stage')){const type=host.querySelector('[data-equipment]').value;config.route.push({type,time:20,gasNLmin:260,powderKgMin:0,AlKg:0,oxygenNm3:0,heatKW:0,additions:[]});render()}});render();return {getConfig:()=>structuredClone(config),recalculate:calculate};
}

